"""Exceptions raised by the lakeformation service."""

from moto.core.exceptions import JsonRESTError


class EntityNotFound(JsonRESTError):
    def __init__(self) -> None:
        super().__init__("EntityNotFoundException", "Entity not found")


class InvalidInput(JsonRESTError):
    def __init__(self, message: str) -> None:
        super().__init__("InvalidInputException", message)


class AlreadyExistsException(JsonRESTError):
    def __init__(self, resource_arn: str) -> None:
        super().__init__(
            "AlreadyExistsException", 
            f"Resource with ARN '{resource_arn}' is already registered"
        )

def register_resource(self, resource_arn: str, role_arn: str) -> None:
    if resource_arn in self.resources:
        raise AlreadyExistsException(resource_arn)
    self.resources[resource_arn] = Resource(resource_arn, role_arn)
